name: Release VSIX

on:
  push:
    tags:
      - 'v*'

permissions:
  contents: write

concurrency:
  group: release-${{ github.ref }}
  cancel-in-progress: false

jobs:
  release:
    if: ${{ !github.event.deleted }}
    runs-on: ubuntu-latest
    timeout-minutes: 15
    steps:
      - uses: actions/checkout@3d3c42e5aac5ba805825da76410c181273ba90b1 # v7.0.1
        with:
          ref: ${{ github.sha }}
          persist-credentials: false

      - uses: actions/setup-node@820762786026740c76f36085b0efc47a31fe5020 # v7.0.0
        with:
          node-version: '22'
          package-manager-cache: false

      - name: Check version and prepare release notes
        run: |
          node <<'NODE'
          const fs = require('node:fs');
          const path = require('node:path');
          const { version } = JSON.parse(fs.readFileSync('package.json', 'utf8'));
          if (process.env.GITHUB_REF_NAME !== `v${version}`) {
            throw new Error('The tag must match the version in package.json.');
          }

          const lines = fs.readFileSync('CHANGELOG.md', 'utf8').split(/\r?\n/);
          const start = lines.indexOf(`## ${version}`);
          if (start === -1) {
            throw new Error(`CHANGELOG.md is missing the ## ${version} section.`);
          }
          const next = lines.findIndex((line, index) => index > start && line.startsWith('## '));
          const notes = lines.slice(start + 1, next === -1 ? lines.length : next).join('\n').trim();
          if (!notes) {
            throw new Error('The release notes must not be empty.');
          }
          fs.writeFileSync(path.join(process.env.RUNNER_TEMP, 'release-notes.md'), `${notes}\n`);
          fs.appendFileSync(process.env.GITHUB_ENV, `VERSION=${version}\n`);
          NODE

      - run: npm ci
      - run: npm test

      - name: Package VSIX
        run: npx --yes @vscode/vsce@4.0.0 package --out "$RUNNER_TEMP/ollama-vscode-$VERSION.vsix"

      - name: Create draft release with VSIX
        env:
          GH_TOKEN: ${{ github.token }}
        run: |
          releases=$(gh api --paginate "repos/$GITHUB_REPOSITORY/releases" --jq '.[].tag_name')
          while IFS= read -r tag; do
            if [ "$tag" = "$GITHUB_REF_NAME" ]; then
              echo "A release already exists for $tag. Leaving it and its assets unchanged." >&2
              exit 1
            fi
          done <<< "$releases"

          gh release create "$GITHUB_REF_NAME" "$RUNNER_TEMP/ollama-vscode-$VERSION.vsix" \
            --repo "$GITHUB_REPOSITORY" \
            --verify-tag \
            --draft \
            --title "$GITHUB_REF_NAME" \
            --notes-file "$RUNNER_TEMP/release-notes.md"

{
  "name": "ollama",
  "displayName": "Ollama",
  "description": "Ollama language model provider for VS Code.",
  "publisher": "Ollama",
  "version": "0.0.13",
  "icon": "images/icon.png",
  "license": "MIT",
  "repository": {
    "type": "git",
    "url": "https://github.com/ollama/ollama-vscode.git"
  },
  "engines": {
    "vscode": "^1.127.0"
  },
  "categories": [
    "AI"
  ],
  "keywords": [
    "ollama",
    "gemma",
    "kimi-k3",
    "glm-5.2",
    "copilot",
    "agent"
  ],
  "activationEvents": [
    "onStartupFinished",
    "onLanguageModelChatProvider:ollama-models"
  ],
  "main": "./out/extension.js",
  "contributes": {
    "languageModelChatProviders": [
      {
        "vendor": "ollama-models",
        "displayName": "Ollama",
        "configuration": {
          "type": "object",
          "properties": {
            "url": {
              "type": "string",
              "title": "Ollama URL",
              "default": "http://127.0.0.1:11434",
              "description": "Base URL for the Ollama server."
            },
            "models": {
              "type": "array",
              "title": "Models",
              "description": "Optional model names to expose from this Ollama server. When omitted, all /api/tags models are exposed.",
              "items": {
                "type": "string"
              }
            },
            "headers": {
              "type": "object",
              "title": "Headers",
              "default": {},
              "description": "Additional HTTP headers to include with Ollama model discovery and chat requests.",
              "additionalProperties": {
                "type": "string"
              }
            }
          }
        }
      }
    ],
    "configuration": [
      {
        "title": "Ollama",
        "properties": {
          "ollama.endpoint": {
            "type": "string",
            "default": "http://127.0.0.1:11434",
            "description": "Base URL for the Ollama server. Provider configuration from VS Code takes precedence when present."
          },
          "ollama.headers": {
            "type": "object",
            "default": {},
            "description": "Additional HTTP headers to include with Ollama model discovery and chat requests.",
            "additionalProperties": {
              "type": "string"
            }
          },
          "ollama.thinkingLevels": {
            "type": "object",
            "default": {},
            "markdownDescription": "Thinking effort overrides by exact Ollama model name, including its tag (for example, `gpt-oss:20b`: `\"low\"`). Values must be supported by that model: a named effort or a boolean to enable/disable thinking. Unset or unsupported values use the server default. Changes apply to the next request.",
            "additionalProperties": {
              "type": ["string", "boolean"]
            }
          },
          "ollama.inferenceTimeoutMinutes": {
            "type": "integer",
            "default": 10,
            "minimum": 1,
            "maximum": 60,
            "description": "Maximum time to wait for Ollama to begin an inference response. Enter a whole number from 1 to 60 minutes. Cancelling Chat still stops the request immediately."
          }
        }
      }
    ],
    "commands": [
      {
        "command": "ollama.refreshModels",
        "title": "Ollama: Refresh Models"
      },
      {
        "command": "ollama.diagnoseModels",
        "title": "Ollama: Diagnose Models"
      }
    ]
  },
  "scripts": {
    "compile": "tsc -p ./",
    "test": "npm run compile && node --test",
    "vscode:prepublish": "npm run compile",
    "watch": "tsc -watch -p ./"
  },
  "devDependencies": {
    "@types/node": "^22.0.0",
    "@types/vscode": "^1.120.0",
    "typescript": "^5.8.0"
  },
  "dependencies": {
    "ollama": "^0.6.3",
    "undici": "^7.28.0"
  }
}

const assert = require('node:assert/strict');
const { execFile } = require('node:child_process');
const http = require('node:http');
const { promisify } = require('node:util');
const test = require('node:test');

if (process.argv.includes('--lifetime-probe')) {
  runProbe().catch(error => {
    console.error(error);
    process.exitCode = 1;
  });
} else {
  test('keeps an SDK stream alive while context checking delays reading', async () => {
    await promisify(execFile)(process.execPath, [
      '--expose-gc', __filename, '--lifetime-probe'
    ], { timeout: 10000 });
  });

  test('still aborts an unread SDK stream when cancellation is requested', async () => {
    const { Ollama } = require('ollama');
    const { createChatFetch } = require('../out/chatFetch');
    const server = http.createServer((request, response) => {
      request.resume();
      response.writeHead(200, { 'content-type': 'application/x-ndjson' });
      response.write('{"message":{"content":"partial"},"done":false}\n');
    });
    await new Promise(resolve => server.listen(0, '127.0.0.1', resolve));
    const transport = createChatFetch(1000);
    const client = new Ollama({
      host: `http://127.0.0.1:${server.address().port}`,
      fetch: transport.fetch
    });
    try {
      const stream = await client.chat({ model: 'test-model', messages: [], stream: true });
      stream.abort();
      await assert.rejects(async () => {
        for await (const chunk of stream) {
          void chunk;
        }
      }, error => error.name === 'AbortError');
    } finally {
      transport.dispose();
      await new Promise(resolve => server.close(resolve));
    }
  });
}

async function runProbe() {
  const { Ollama } = require('ollama');
  const { createChatFetch } = require('../out/chatFetch');
  assert.equal(typeof global.gc, 'function');

  let finishResponse;
  const finish = new Promise(resolve => { finishResponse = resolve; });
  const server = http.createServer(async (request, response) => {
    request.resume();
    response.writeHead(200, { 'content-type': 'application/x-ndjson' });
    response.write('{"message":{"content":"hello"},"done":false}\n');
    await finish;
    if (!response.destroyed) {
      response.end('{"message":{"content":" world"},"done":true}\n');
    }
  });
  await new Promise(resolve => server.listen(0, '127.0.0.1', resolve));
  const transport = createChatFetch(1000);
  const client = new Ollama({
    host: `http://127.0.0.1:${server.address().port}`,
    fetch: transport.fetch
  });

  try {
    const stream = await client.chat({
      model: 'test-model',
      messages: [{ role: 'user', content: 'hello' }],
      stream: true
    });
    // The provider awaits its context check after chat() returns the lazy
    // iterator. Collect the SDK's Response during that gap, before getReader().
    for (let i = 0; i < 10; i++) {
      await new Promise(resolve => setTimeout(resolve, 10));
      global.gc();
    }
    finishResponse();
    const chunks = [];
    for await (const chunk of stream) {
      chunks.push(chunk);
    }
    assert.equal(chunks.at(-1).done, true);
    assert.equal(chunks.map(chunk => chunk.message?.content || '').join(''), 'hello world');
  } finally {
    finishResponse();
    transport.dispose();
    await new Promise(resolve => server.close(resolve));
  }
}

const assert = require('node:assert/strict');
const test = require('node:test');

const {
  supportedThinkingLevel,
  thinkingPolicy
} = require('../out/thinking');

test('uses documented GPT-OSS effort levels and does not offer disabling', () => {
  assert.deepEqual(thinkingPolicy('gpt-oss:20b'), {
    levels: ['low', 'medium', 'high'],
    defaultLevel: 'medium'
  });
  assert.deepEqual(thinkingPolicy('custom-name', 'gptoss'), {
    levels: ['low', 'medium', 'high'],
    defaultLevel: 'medium'
  });
});

test('uses documented DeepSeek V4 non-thinking, high, and max modes', () => {
  const expected = {
    levels: [false, 'high', 'max'],
    defaultLevel: false
  };

  assert.deepEqual(thinkingPolicy('deepseek-v4-flash:cloud'), expected);
  assert.deepEqual(thinkingPolicy('deepseek-v4-pro:cloud'), expected);
});

test('uses documented GLM 5.2 high and max effort levels', () => {
  const expected = {
    levels: ['high', 'max'],
    defaultLevel: 'high'
  };

  assert.deepEqual(thinkingPolicy('glm-5.2:cloud'), expected);
  assert.deepEqual(thinkingPolicy('custom-name', 'glm5.2'), expected);
});

test('does not expose a control for models without a verified mapping', () => {
  assert.equal(thinkingPolicy('qwen3.6:35b'), undefined);
  assert.equal(thinkingPolicy('my-deepseek-v4-experiment'), undefined);
});

test('uses Qwen3.8 metadata without inventing high/max aliases or a default', () => {
  for (const defaultLevel of ['medium', 'xhigh']) {
    const policy = thinkingPolicy('qwen3.8:27b', 'qwen35', {
      values: [false, 'low', 'medium', 'xhigh'], default: defaultLevel
    });
    assert.deepEqual(policy, { levels: [false, 'low', 'medium', 'xhigh'], defaultLevel });
    for (const value of policy.levels) assert.equal(supportedThinkingLevel(policy, value), value);
    for (const value of ['high', 'max', 'none', true, null, 1, {}, '']) {
      assert.equal(supportedThinkingLevel(policy, value), undefined);
    }
  }
  assert.equal(thinkingPolicy('qwen3.8:27b', 'qwen35'), undefined);
});

test('metadata overrides old mappings and supports exact boolean and named values', () => {
  assert.deepEqual(thinkingPolicy('glm-5.2:cloud', undefined, {
    values: [false, 'high', 'max'], default: 'high'
  }), { levels: [false, 'high', 'max'], defaultLevel: 'high' });
  assert.deepEqual(thinkingPolicy('custom-model', undefined, {
    values: [false, true], default: true
  }), { levels: [false, true], defaultLevel: true });
  const policy = thinkingPolicy('custom-model', undefined, {
    values: ['brief', 'deep'], default: 'brief'
  });
  assert.equal(supportedThinkingLevel(policy, 'deep'), 'deep');
  assert.equal(supportedThinkingLevel(policy, 'high'), undefined);
});

test('non-configurable or malformed metadata hides controls instead of falling back', () => {
  for (const metadata of [null, false, {}, {values: []},
    { values: [false], default: false }, { values: [true], default: true },
    { values: ['high', 'high'], default: 'high' },
    { values: ['low', 'high'], default: 'medium' },
    { values: ['low', 5], default: 'low' }, { values: ['', 'high'], default: 'high' }
  ]) assert.equal(thinkingPolicy('gpt-oss:20b', 'gptoss', metadata), undefined);
});

test('accepts only levels supported by the selected model policy', () => {
  const gptOSS = thinkingPolicy('gpt-oss:20b');
  assert.equal(supportedThinkingLevel(gptOSS, undefined), undefined);
  assert.equal(supportedThinkingLevel(gptOSS, 'low'), 'low');
  assert.equal(supportedThinkingLevel(gptOSS, 'none'), undefined);

  const deepSeekV4 = thinkingPolicy('deepseek-v4-flash:cloud');
  assert.equal(supportedThinkingLevel(deepSeekV4, undefined), undefined);
  assert.equal(supportedThinkingLevel(deepSeekV4, 'max'), 'max');
  assert.equal(supportedThinkingLevel(deepSeekV4, 'low'), undefined);

  const glm52 = thinkingPolicy('glm-5.2:cloud');
  assert.equal(supportedThinkingLevel(glm52, undefined), undefined);
  assert.equal(supportedThinkingLevel(glm52, 'high'), 'high');
  assert.equal(supportedThinkingLevel(glm52, 'medium'), undefined);
});

test('omits stale configuration for models without a verified policy', () => {
  assert.equal(supportedThinkingLevel(undefined, 'high'), undefined);
  assert.equal(supportedThinkingLevel(undefined, 'invalid'), undefined);
});

const assert = require('node:assert/strict');
const test = require('node:test');
const {
  inspectOllamaModels,
  loadedModelContextDiagnosticLines,
  maximumSupportedContextLength,
  OllamaDiagnosticsConfigurationTracker,
  ollamaDiagnosticsClientOptions,
  thinkingDiagnosticLines
} = require('../out/diagnostics');

test('uses the most recently resolved provider group when the workspace endpoint differs', () => {
  const tracker = new OllamaDiagnosticsConfigurationTracker();
  const workspaceConfiguration = {
    url: 'https://workspace.example.test',
    headers: { Authorization: 'Bearer workspace' }
  };
  tracker.recordResolved({
    url: 'https://previous-provider.example.test',
    headers: { Authorization: 'Bearer previous-provider' }
  });
  tracker.recordResolved({
    url: 'https://provider.example.test',
    headers: { Authorization: 'Bearer provider' }
  });

  const selected = tracker.select(workspaceConfiguration);

  assert.equal(selected.source, 'resolved-provider-group');
  assert.deepEqual(selected.configuration, {
    url: 'https://provider.example.test',
    headers: { Authorization: 'Bearer provider' }
  });
});

test('prefers the most recently used provider group for diagnostics', () => {
  const tracker = new OllamaDiagnosticsConfigurationTracker();
  tracker.recordResolved({
    url: 'https://resolved.example.test',
    headers: { 'X-Ollama-Group': 'resolved' }
  });
  tracker.recordUsed({
    url: 'https://used.example.test',
    headers: { 'X-Ollama-Group': 'used' }
  });

  const selected = tracker.select({
    url: 'https://workspace.example.test',
    headers: {}
  });

  assert.equal(selected.source, 'used-provider-group');
  assert.deepEqual(selected.configuration, {
    url: 'https://used.example.test',
    headers: { 'X-Ollama-Group': 'used' }
  });
});

test('preserves endpoint, string headers, and cancellation-aware fetch in client options', () => {
  const request = async () => new Response();
  const options = ollamaDiagnosticsClientOptions(
    'https://ollama.example.test',
    {
      Authorization: 'Bearer secret',
      'X-Ollama-Count': 2,
      'X-Ollama-Disabled': false
    },
    request
  );

  assert.equal(options.host, 'https://ollama.example.test');
  assert.deepEqual(options.headers, { Authorization: 'Bearer secret' });
  assert.equal(options.fetch, request);
});

test('queries loaded models and reuses tags metadata through the diagnostics client', async () => {
  const calls = [];
  const inspection = await inspectOllamaModels({
    async list() {
      calls.push('list');
      return {
        models: [{ name: 'gemma3:latest', details: { context_length: 131072 } }]
      };
    },
    async ps() {
      calls.push('ps');
      return {
        models: [{ name: 'gemma3:latest', context_length: 32768 }]
      };
    },
    async show() {
      assert.fail('tag metadata should avoid an additional lookup');
    }
  });

  assert.deepEqual(calls, ['list', 'ps']);
  assert.deepEqual(inspection.availableModels, ['gemma3:latest']);
  assert.deepEqual(inspection.loadedModelLines, [
    'Ollama reports 1 loaded local model(s):',
    '- gemma3:latest: runtime context allocation: 32K; maximum supported context: 128K; WARNING: runtime allocation is below the recommended 64K'
  ]);
});

test('keeps available model diagnostics when the loaded-model request fails', async () => {
  const psError = new Error('ps unavailable');
  const inspection = await inspectOllamaModels({
    async list() {
      return { models: [{ name: 'gemma3:latest' }] };
    },
    async ps() {
      throw psError;
    },
    async show() {
      assert.fail('a failed process lookup should not request model metadata');
    }
  });

  assert.deepEqual(inspection.availableModels, ['gemma3:latest']);
  assert.equal(inspection.loadedModelLines, undefined);
  assert.equal(inspection.loadedModelsError, psError);
});

test('uses show metadata when tags fail but loaded models are available', async () => {
  const listError = new Error('tags unavailable');
  let shownModel;
  const inspection = await inspectOllamaModels({
    async list() {
      throw listError;
    },
    async ps() {
      return {
        models: [{ model: 'qwen3.5:latest', context_length: 65536 }]
      };
    },
    async show({ model }) {
      shownModel = model;
      return { model_info: { 'qwen3.context_length': 262144 } };
    }
  });

  assert.equal(inspection.availableModels, undefined);
  assert.equal(inspection.availableModelsError, listError);
  assert.equal(shownModel, 'qwen3.5:latest');
  assert.deepEqual(inspection.loadedModelLines, [
    'Ollama reports 1 loaded local model(s):',
    '- qwen3.5:latest: runtime context allocation: 64K; maximum supported context: 256K'
  ]);
});

test('flags a loaded model whose runtime context allocation is below 64K', async () => {
  const lines = await loadedModelContextDiagnosticLines([
    { name: 'gemma3:latest', context_length: 32768 }
  ], [
    { name: 'gemma3:latest', details: { context_length: 131072 } }
  ], async () => {
    assert.fail('tag metadata should avoid an additional lookup');
  });

  assert.deepEqual(lines, [
    'Ollama reports 1 loaded local model(s):',
    '- gemma3:latest: runtime context allocation: 32K; maximum supported context: 128K; WARNING: runtime allocation is below the recommended 64K'
  ]);
});

test('reports a sufficient loaded runtime context allocation without a warning', async () => {
  const lines = await loadedModelContextDiagnosticLines([
    {
      model: 'qwen3.5:latest',
      context_length: 65536
    }
  ], [], async model => {
    assert.equal(model, 'qwen3.5:latest');
    return { max_context_length: 262144 };
  });

  assert.deepEqual(lines, [
    'Ollama reports 1 loaded local model(s):',
    '- qwen3.5:latest: runtime context allocation: 64K; maximum supported context: 256K'
  ]);
});

test('explains how to populate diagnostics when no local model is loaded', async () => {
  const lines = await loadedModelContextDiagnosticLines([], [], async () => {
    assert.fail('an empty process list should not request model metadata');
  });

  assert.deepEqual(lines, [
    'No local models are currently loaded. Send a prompt to a local Ollama model, then rerun `Ollama: Diagnose Models`.'
  ]);
});

test('reads maximum context only from model metadata supplied separately from the runtime process', () => {
  assert.equal(maximumSupportedContextLength({ context_length: 131072 }), 131072);
  assert.equal(maximumSupportedContextLength({
    model_info: { 'gemma3.context_length': 131072 }
  }), 131072);
});

test('formats thinking diagnostics with server-advertised default and effective setting for next request', () => {
  const models = [{
    model: 'server/qwen3.8:27b',
    thinkingPolicy: { levels: [false, 'low', 'medium', 'xhigh'], defaultLevel: 'medium' },
    defaultSource: 'server'
  }];
  const lines = thinkingDiagnosticLines(models, { 'server/qwen3.8:27b': 'low' });

  assert.deepEqual(lines, [
    'Thinking settings:',
    '- server/qwen3.8:27b: supported values: [false, "low", "medium", "xhigh"]; server-advertised default: "medium"; configured override: "low"; effective setting for next request: "low"'
  ]);
});

test('distinguishes compatibility fallback defaults and explains omitted think when override is unset', () => {
  const models = [{
    model: 'gpt-oss:20b',
    thinkingPolicy: { levels: ['low', 'medium', 'high'], defaultLevel: 'medium' },
    defaultSource: 'compatibility'
  }];
  const lines = thinkingDiagnosticLines(models, {});

  assert.deepEqual(lines, [
    'Thinking settings:',
    '- gpt-oss:20b: supported values: ["low", "medium", "high"]; compatibility fallback default: "medium"; configured override: none; think will be omitted to use server default'
  ]);
});

test('explains why an unsupported override is ignored and that think will be omitted', () => {
  const models = [{
    model: 'deepseek-v4-flash:cloud',
    thinkingPolicy: { levels: [false, 'high', 'max'], defaultLevel: false },
    defaultSource: 'compatibility'
  }];
  const lines = thinkingDiagnosticLines(models, { 'deepseek-v4-flash:cloud': 'low' });

  assert.deepEqual(lines, [
    'Thinking settings:',
    '- deepseek-v4-flash:cloud: supported values: [false, "high", "max"]; compatibility fallback default: false; configured override: "low" (unsupported, ignored); think will be omitted to use server default'
  ]);
});

test('supports boolean configured thinking overrides', () => {
  const models = [{
    model: 'deepseek-v4-flash:cloud',
    thinkingPolicy: { levels: [false, 'high', 'max'], defaultLevel: false },
    defaultSource: 'compatibility'
  }];
  const lines = thinkingDiagnosticLines(models, { 'deepseek-v4-flash:cloud': false });

  assert.deepEqual(lines, [
    'Thinking settings:',
    '- deepseek-v4-flash:cloud: supported values: [false, "high", "max"]; compatibility fallback default: false; configured override: false; effective setting for next request: false'
  ]);
});

test('explains unavailable overrides without inferring that a model cannot think', () => {
  const nonThinking = [{ model: 'llama3:8b' }];
  assert.deepEqual(thinkingDiagnosticLines([], {}), []);
  assert.deepEqual(thinkingDiagnosticLines(nonThinking, {}), [
    'Thinking settings:',
    '- llama3:8b: configurable thinking values unavailable; configured override: none; think will be omitted to use server default'
  ]);

  const linesWithOverride = thinkingDiagnosticLines(nonThinking, { 'llama3:8b': 'high' });
  assert.deepEqual(linesWithOverride, [
    'Thinking settings:',
    '- llama3:8b: configurable thinking values unavailable; configured override: "high" (ignored); think will be omitted to use server default'
  ]);
});

test('handles malformed thinking levels gracefully', () => {
  const models = [{
    model: 'gpt-oss:20b',
    thinkingPolicy: { levels: ['low', 'medium', 'high'], defaultLevel: 'medium' },
    defaultSource: 'compatibility'
  }];
  for (const malformed of [null, undefined, false, 'invalid', [1, 2]]) {
    const lines = thinkingDiagnosticLines(models, malformed);
    assert.deepEqual(lines, [
      'Thinking settings:',
      '- gpt-oss:20b: supported values: ["low", "medium", "high"]; compatibility fallback default: "medium"; configured override: none; think will be omitted to use server default'
    ]);
  }
});

const assert = require('node:assert/strict');
const Module = require('node:module');
const test = require('node:test');

const originalLoad = Module._load;
Module._load = function(request, parent, isMain) {
  if (request === 'vscode') {
    return {};
  }
  return originalLoad.call(this, request, parent, isMain);
};

let isMissingStreamCompletionError;
try {
  ({ isMissingStreamCompletionError } = require('../out/provider'));
} finally {
  Module._load = originalLoad;
}

test('recognises the Ollama client missing-completion error', () => {
  assert.equal(
    isMissingStreamCompletionError(new Error('Did not receive done or success response in stream.')),
    true
  );
});

test('does not hide unrelated stream errors', () => {
  assert.equal(isMissingStreamCompletionError(new Error('connection reset')), false);
  assert.equal(isMissingStreamCompletionError('stream ended'), false);
});

const assert = require('node:assert/strict');
const Module = require('node:module');
const test = require('node:test');

class LanguageModelTextPart {
  constructor(value) {
    this.value = value;
  }
}

class LanguageModelDataPart {
  constructor(data, mimeType) {
    this.mimeType = mimeType;
    this.data = data;
  }

  toJSON() {
    return {
      $mid: 24,
      mimeType: this.mimeType,
      data: Buffer.from(this.data).toString('base64')
    };
  }
}

class LanguageModelToolCallPart {}

class LanguageModelToolResultPart {
  constructor(callId, content) {
    this.callId = callId;
    this.content = content;
  }
}

const vscode = {
  LanguageModelChatMessageRole: { User: 1, Assistant: 2, System: 3 },
  LanguageModelDataPart,
  LanguageModelTextPart,
  LanguageModelToolCallPart,
  LanguageModelToolResultPart
};

const originalLoad = Module._load;
Module._load = function(request, parent, isMain) {
  if (request === 'vscode') {
    return vscode;
  }
  return originalLoad.call(this, request, parent, isMain);
};

let toOllamaMessages;
let toOllamaTools;
try {
  ({ toOllamaMessages, toOllamaTools } = require('../out/convert'));
} finally {
  Module._load = originalLoad;
}

test('preserves nonempty tool schemas including constraints and unsupported features', () => {
  const schemas = [
    { type: 'object', properties: { city: { type: 'string', enum: ['Toronto'] } }, required: ['city'], additionalProperties: false },
    { anyOf: [{ type: 'object', properties: {} }, { type: 'null' }] },
    { $ref: '#/$defs/input', $defs: { input: { type: 'object' } } },
    { properties: { value: { type: 'string' } } },
    { type: '', properties: null }
  ].map(Object.freeze);
  for (const inputSchema of schemas) {
    const tool = Object.freeze({ name: 'example', description: 'Example tool.', inputSchema });
    assert.equal(toOllamaTools([tool])[0].function.parameters, inputSchema);
  }
});

test('omits cache control and unrecognized provider metadata from tool results', () => {
  const result = new LanguageModelToolResultPart('call-1', [
    new LanguageModelTextPart('first'),
    new LanguageModelDataPart(new TextEncoder().encode('ephemeral'), 'cache_control'),
    new LanguageModelDataPart(new TextEncoder().encode('provider metadata'), 'application/vnd.provider.metadata'),
    new LanguageModelDataPart(new TextEncoder().encode('second'), 'text/plain')
  ]);

  assert.deepEqual(toOllamaMessages([{ role: 1, content: [result] }]), [{
    role: 'tool',
    content: 'first\nsecond',
    tool_call_id: 'call-1'
  }]);
});

test('preserves an empty tool result when it only contains provider metadata', () => {
  const result = new LanguageModelToolResultPart('call-2', [
    new LanguageModelDataPart(new TextEncoder().encode('ephemeral'), 'cache_control'),
    new LanguageModelDataPart(new TextEncoder().encode('provider metadata'), 'application/vnd.provider.metadata')
  ]);

  assert.deepEqual(toOllamaMessages([{ role: 1, content: [result] }]), [{
    role: 'tool',
    content: '',
    tool_call_id: 'call-2'
  }]);
});

test('preserves text, supported JSON data, and JSON-compatible tool result content', () => {
  const result = new LanguageModelToolResultPart('call-3', [
    new LanguageModelTextPart('first'),
    new LanguageModelDataPart(new TextEncoder().encode('second'), 'text/plain'),
    new LanguageModelDataPart(new TextEncoder().encode('{"status":"ok"}'), 'application/json; charset=utf-8'),
    new LanguageModelDataPart(new TextEncoder().encode('{"vendor":true}'), 'application/vnd.example+json'),
    { legacy: true }
  ]);

  assert.deepEqual(toOllamaMessages([{ role: 1, content: [result] }]), [{
    role: 'tool',
    content: 'first\nsecond\n{"status":"ok"}\n{"vendor":true}\n{"legacy":true}',
