test('links VS Code cancellation to the chat request', async () => {
  let requestClosed;
  let markRequestStarted;
  const requestStarted = new Promise(resolve => {
    markRequestStarted = resolve;
  });
  await withServer(request => {
    request.resume();
    requestClosed = new Promise(resolve => request.on('close', resolve));
    markRequestStarted();
  }, async url => {
    const source = cancellationTokenSource();
    const disposables = [];
    const transport = createChatFetch(1000);
    const request = createFetch(source.token, disposables, transport.fetch);

    try {
      const pending = request(`${url}/api/chat`, { method: 'POST', body: '{}' });
      await requestStarted;
      source.cancel();
      await assert.rejects(pending, error => error.name === 'AbortError');
      await requestClosed;
    } finally {
      disposeAll(disposables);
      transport.dispose();
    }
  });
});

function cancellationTokenSource() {
  const listeners = new Set();
  let cancelled = false;

  return {
    token: {
      get isCancellationRequested() {
        return cancelled;
      },
      onCancellationRequested(listener) {
        listeners.add(listener);
        return { dispose: () => listeners.delete(listener) };
      }
    },
    cancel() {
      cancelled = true;
      for (const listener of listeners) {
        listener();
      }
    }
  };
}

async function withServer(handler, run) {
  const server = http.createServer(handler);
  await new Promise((resolve, reject) => {
    server.once('error', reject);
    server.listen(0, '127.0.0.1', resolve);
  });

  const address = server.address();
  try {
    await run(`http://127.0.0.1:${address.port}`);
  } finally {
    await new Promise((resolve, reject) => server.close(error => error ? reject(error) : resolve()));
  }
}

async function withHttpsServer(handler, run) {
  const server = https.createServer({
    cert: testServerCertificate,
    key: testServerKey
  }, handler);
  await new Promise((resolve, reject) => {
    server.once('error', reject);
    server.listen(0, '127.0.0.1', resolve);
  });

  const address = server.address();
  try {
    await run(`https://127.0.0.1:${address.port}`);
  } finally {
    await new Promise((resolve, reject) => server.close(error => error ? reject(error) : resolve()));
  }
}

async function withTimeout(promise, milliseconds) {
  let timer;
  const timeout = new Promise((_, reject) => {
    timer = setTimeout(() => reject(new Error(`Timed out after ${milliseconds}ms`)), milliseconds);
  });
  try {
    return await Promise.race([promise, timeout]);
  } finally {
    clearTimeout(timer);
  }
}

const assert = require('node:assert/strict');
const Module = require('node:module');
const test = require('node:test');

class Disposable {
  dispose() {}
}

class EventEmitter {
  event = () => new Disposable();
  fire() {}
  dispose() {}
}

class CancellationTokenSource {
  token = cancellationToken;
  cancel() {}
  dispose() {}
}

class LanguageModelTextPart {
  constructor(value) {
    this.value = value;
  }
}

class LanguageModelDataPart {
  constructor(data, mimeType) {
    this.data = data;
    this.mimeType = mimeType;
  }
}

class LanguageModelToolCallPart {}
class LanguageModelToolResultPart {}

const cancellationToken = {
  isCancellationRequested: false,
  onCancellationRequested: () => new Disposable()
};

const vscode = {
  CancellationError: class CancellationError extends Error {},
  CancellationTokenSource,
  EventEmitter,
  LanguageModelChatMessageRole: { User: 1, Assistant: 2, System: 3 },
  LanguageModelDataPart,
  LanguageModelTextPart,
  LanguageModelToolCallPart,
  LanguageModelToolResultPart,
  commands: { executeCommand: async () => undefined },
  env: { openExternal: async () => undefined },
  window: {
    showErrorMessage: async () => undefined,
    showWarningMessage: async () => undefined
  },
  workspace: {
    getConfiguration: () => ({ get: (key, fallback) => key in settings ? settings[key] : fallback })
  }
};

let models = [];
let chatRequests = [];
let settings = {};

class Ollama {
  async version() {
    return { version: 'test' };
  }

  async list() {
    return { models };
  }

  async show({ model }) {
    return models.find(candidate => (candidate.model || candidate.name) === model)?.show ?? {};
  }

  async chat(request) {
    chatRequests.push(request);
    return {
      abort() {},
      async *[Symbol.asyncIterator]() {
        yield { done: true, message: {} };
      }
    };
  }
}

const originalLoad = Module._load;
Module._load = function(request, parent, isMain) {
  if (request === 'vscode') {
    return vscode;
  }
  if (request === 'ollama') {
    return { Ollama };
  }
  return originalLoad.call(this, request, parent, isMain);
};

let OllamaLanguageModelProvider;
try {
  ({ OllamaLanguageModelProvider } = require('../out/provider'));
} finally {
  Module._load = originalLoad;
}

