import * as vscode from 'vscode';
import { Ollama } from 'ollama';
import { OllamaLanguageModelProvider, createFetch, disposeAll } from './provider';
import {
  inspectOllamaModels,
  ollamaDiagnosticsClientOptions,
  type OllamaDiagnosticsConfigurationSource
} from './diagnostics';

const defaultOllamaURL = 'http://127.0.0.1:11434';
const ollamaVendor = 'ollama-models';

export function activate(context: vscode.ExtensionContext) {
  const output = vscode.window.createOutputChannel('Ollama');
  const provider = new OllamaLanguageModelProvider(output);

  output.appendLine('Activated Ollama language model provider.');

  context.subscriptions.push(
    output,
    provider,
    vscode.lm.registerLanguageModelChatProvider(ollamaVendor, provider),
    vscode.commands.registerCommand('ollama.refreshModels', () => provider.refresh()),
    vscode.commands.registerCommand('ollama.diagnoseModels', () => diagnoseModels(output, provider))
  );
}

export function deactivate() {}

async function diagnoseModels(output: vscode.OutputChannel, provider: OllamaLanguageModelProvider) {
  output.show(true);
  output.appendLine('--- Diagnostics ---');

  provider.resetThinkingDiagnostics();
  const allVSCodeModels = await vscode.lm.selectChatModels();
  output.appendLine(`VS Code returned ${allVSCodeModels.length} total language model(s).`);
  for (const model of allVSCodeModels) {
    output.appendLine(`- ${model.vendor}/${model.id} (${model.name})`);
  }

  const ollamaVSCodeModels = allVSCodeModels.filter(model => model.vendor === ollamaVendor);
  output.appendLine(`VS Code returned ${ollamaVSCodeModels.length} Ollama language model(s).`);

  const settings = vscode.workspace.getConfiguration('ollama');
  for (const line of provider.getThinkingDiagnosticLines(settings.get<unknown>('thinkingLevels'))) {
    output.appendLine(line);
  }

  await inspectDirectOllamaModels(output, provider);

  output.appendLine('--- End Diagnostics ---');
}

async function inspectDirectOllamaModels(
  output: vscode.OutputChannel,
  provider: OllamaLanguageModelProvider
): Promise<void> {
  const settings = vscode.workspace.getConfiguration('ollama');
  const workspaceEndpoint = settings.get<string>('endpoint', defaultOllamaURL) || defaultOllamaURL;
  const selected = provider.selectDiagnosticsConfiguration({
    url: workspaceEndpoint,
    headers: getConfiguredHeaders(settings)
  });
  const { url: endpoint, headers } = selected.configuration;
  output.appendLine(
    `Direct Ollama API is inspecting ${configurationSourceLabel(selected.source)} at ${endpoint}.`
  );
  const source = new vscode.CancellationTokenSource();
  const disposables: vscode.Disposable[] = [source];
  const ollama = new Ollama(ollamaDiagnosticsClientOptions(
    endpoint,
    headers,
    createFetch(source.token, disposables)
  ));
  const timer = setTimeout(() => source.cancel(), 5000);
  try {
    const inspection = await inspectOllamaModels(ollama);

    if (inspection.availableModels !== undefined) {
      const availableModelNames = inspection.availableModels;
      if (availableModelNames.length > 0) {
        output.appendLine(`Direct Ollama API returned ${availableModelNames.length} model(s).`);
        for (const model of availableModelNames.slice(0, 20)) {
          output.appendLine(`- ${model}`);
        }
        if (availableModelNames.length > 20) {
          output.appendLine(`... ${availableModelNames.length - 20} more`);
        }
      }
    } else {
      output.appendLine(`Direct Ollama API failed at ${endpoint}: ${formatError(inspection.availableModelsError)}`);
    }

    if (inspection.loadedModelLines !== undefined) {
      for (const line of inspection.loadedModelLines) {
        output.appendLine(line);
      }
    } else {
      output.appendLine(`Could not inspect loaded Ollama models at ${endpoint}: ${formatError(inspection.loadedModelsError)}`);
    }
  } finally {
    clearTimeout(timer);
    disposeAll(disposables);
  }
}

function getConfiguredHeaders(settings: vscode.WorkspaceConfiguration): Record<string, string> {
  const configured = settings.get<Record<string, unknown>>('headers', {});
  const headers: Record<string, string> = {};
  for (const [name, value] of Object.entries(configured)) {
    if (typeof value === 'string') {
      headers[name] = value;
    }
  }
  return headers;
}

function configurationSourceLabel(source: OllamaDiagnosticsConfigurationSource): string {
  switch (source) {
    case 'used-provider-group':
      return 'the most recently used provider group';
    case 'resolved-provider-group':
      return 'the most recently resolved provider group';
    case 'workspace-settings':
      return 'workspace settings';
  }
}

function formatError(error: unknown): string {
  return error instanceof Error ? error.message : String(error);
}

export const defaultInferenceTimeoutMinutes = 10;
export const minimumInferenceTimeoutMinutes = 1;
export const maximumInferenceTimeoutMinutes = 60;

export function inferenceTimeoutMilliseconds(value: unknown): number {
  const minutes = typeof value === 'number'
    && Number.isInteger(value)
    && value >= minimumInferenceTimeoutMinutes
    && value <= maximumInferenceTimeoutMinutes
    ? value
    : defaultInferenceTimeoutMinutes;

  return minutes * 60 * 1000;
}

export const minimumMachineContextLength = 64 * 1024;

interface OllamaProcessModel {
  name?: unknown;
  model?: unknown;
  context_length?: unknown;
}

export function machineContextLength(
  models: readonly unknown[],
  requestedModel: string
): number | undefined {
  const requestedKey = modelKey(requestedModel);

  for (const candidate of models) {
    if (!isRecord(candidate)) {
      continue;
    }

    const model = candidate as OllamaProcessModel;
    const matches = [model.name, model.model].some(name =>
      typeof name === 'string' && modelKey(name) === requestedKey
    );
    if (matches && isPositiveInteger(model.context_length)) {
      return model.context_length;
    }
  }

  return undefined;
}

export async function waitForMachineContextLength(
  listModels: () => Promise<readonly unknown[]>,
  requestedModel: string,
  isRequestSettled: () => boolean,
  waitForNextCheck: () => Promise<boolean>
): Promise<number | undefined> {
  while (true) {
    const settledBeforeCheck = isRequestSettled();
    const contextLength = machineContextLength(await listModels(), requestedModel);
    if (settledBeforeCheck) {
      return contextLength;
    }

    if (isRequestSettled()) {
      // Ignore a result from a lookup that began before the request settled.
      // Check once more now that Ollama has finished loading the model.
      continue;
    }
    if (!await waitForNextCheck()) {
      return undefined;
    }
  }
}

export async function waitForMachineContextCheckBeforeStreaming(
  check: Promise<void>,
  waitForTimeout: () => Promise<void>,
  cancelCheck: () => void
): Promise<void> {
  let checkFinished = false;
  await Promise.race([
    check.finally(() => { checkFinished = true; }),
    waitForTimeout().then(() => {
      if (!checkFinished) {
        cancelCheck();
      }
    })
  ]);
}

export function isMachineContextTooSmall(contextLength: number): boolean {
  return contextLength < minimumMachineContextLength;
}

export function formatContextLength(contextLength: number): string {
  return contextLength % 1024 === 0
    ? `${contextLength / 1024}K`
    : contextLength.toLocaleString('en-US');
}

function modelKey(name: string): string {
  const normalized = name.trim().toLowerCase();
  return normalized.endsWith(':latest')
    ? normalized.slice(0, -':latest'.length)
    : normalized;
}

function isPositiveInteger(value: unknown): value is number {
  return typeof value === 'number' && Number.isSafeInteger(value) && value > 0;
}

function isRecord(value: unknown): value is Record<string, unknown> {
  return typeof value === 'object' && value !== null && !Array.isArray(value);
}

export function parseContextExceededError(
  error: unknown
): { requestedTokens: number; availableTokens: number } | undefined {
  const message = typeof error === 'string'
    ? error
    : error instanceof Error
    ? error.message
    : isRecord(error) && typeof error.message === 'string'
    ? error.message
    : String(error ?? '');
  const match = message.match(
    /request\s*\((\d+)\s*tokens\)\s*exceeds\s*the\s*available\s*context\s*size\s*\((\d+)\s*tokens\)/i
  );
  if (!match) {
    return undefined;
  }
  const requestedTokens = Number(match[1]);
  const availableTokens = Number(match[2]);
  if (isPositiveInteger(requestedTokens) && isPositiveInteger(availableTokens)
    && requestedTokens > availableTokens) {
    return { requestedTokens, availableTokens };
  }
  return undefined;
}

export function formatContextExceededError(
  exceeded: { requestedTokens: number; availableTokens: number },
  contextWindow: number,
  modelName: string
): string {
  const requested = formatContextLength(exceeded.requestedTokens);
  if (exceeded.requestedTokens > contextWindow) {
    const limit = formatContextLength(contextWindow);
    return `Prompt (${requested} tokens) exceeds ${modelName}'s maximum context window (${limit}). Shorten the prompt or remove attachments to continue.`;
  }
  const allocated = formatContextLength(exceeded.availableTokens);
  return `Prompt (${requested} tokens) exceeds the allocated context window (${allocated}) for ${modelName}. Increase the context window or shorten the prompt to continue.`;
}

import {
  Agent,
  fetch as undiciFetch,
  type RequestInfo as UndiciRequestInfo,
  type RequestInit as UndiciRequestInit
} from 'undici';
import { getCACertificates } from 'node:tls';

interface ChatFetch {
  readonly fetch: typeof globalThis.fetch;
  dispose(): void;
}

export function trustedCACertificates(
  loadCertificates: typeof getCACertificates = getCACertificates
): string[] {
  return [...new Set([
    ...loadCertificates('default'),
    ...loadCertificates('system')
  ])];
}

export function createChatFetch(
  headersTimeout: number,
  loadCertificates: typeof getCACertificates = getCACertificates,
  bodyTimeout = 0
): ChatFetch {
  const dispatcher = new Agent({
    headersTimeout,
    bodyTimeout,
    connect: { ca: trustedCACertificates(loadCertificates) }
  });
  let disposed = false;
  // The Ollama SDK keeps only the body until iteration starts. Keep its Response
  // alive so Undici's finalizer cannot cancel that unread stream.
  const responses = new Set<Response>();

  return {
    fetch: async (input, init) => {
      const response = await undiciFetch(
        input as unknown as UndiciRequestInfo,
        {
          ...(init as unknown as UndiciRequestInit | undefined),
          dispatcher
        }
      ) as unknown as Response;
      responses.add(response);
      return response;
    },
    dispose: () => {
      if (disposed) {
        return;
      }
      disposed = true;
      responses.clear();
      void dispatcher.destroy().catch(() => undefined);
    }
  };
}

import * as vscode from 'vscode';
import { OllamaChatMessage, OllamaTool } from './provider';

export function toOllamaMessages(messages: readonly vscode.LanguageModelChatRequestMessage[]): OllamaChatMessage[] {
  const converted: OllamaChatMessage[] = [];

  for (const message of messages) {
    const text: string[] = [];
    const images: string[] = [];
    const toolCalls: NonNullable<OllamaChatMessage['tool_calls']> = [];
    const toolResults: OllamaChatMessage[] = [];

    for (const part of message.content) {
      if (part instanceof vscode.LanguageModelTextPart) {
        text.push(part.value);
      } else if (part instanceof vscode.LanguageModelDataPart) {
        if (part.mimeType.startsWith('image/')) {
          images.push(Buffer.from(part.data).toString('base64'));
        } else if (part.mimeType.startsWith('text/')) {
          text.push(new TextDecoder().decode(part.data));
        }
      } else if (part instanceof vscode.LanguageModelToolCallPart) {
        toolCalls.push({
          id: part.callId,
          function: {
            name: part.name,
            arguments: part.input as Record<string, unknown>
          }
        });
      } else if (part instanceof vscode.LanguageModelToolResultPart) {
        const result = toolResultContent(part);
        toolResults.push({
          role: 'tool',
          content: result.content,
          ...(result.images.length > 0 ? { images: result.images } : {}),
          tool_call_id: part.callId
        });
      }
    }

    if (text.length > 0 || images.length > 0 || toolCalls.length > 0) {
      converted.push({
        role: roleToOllama(message.role),
        content: text.join('\n'),
        images: images.length > 0 ? images : undefined,
        tool_calls: toolCalls.length > 0 ? toolCalls : undefined
      });
    }

    converted.push(...toolResults);
  }

  return converted;
}

export function toOllamaTools(tools: readonly vscode.LanguageModelChatTool[] | undefined): OllamaTool[] {
  return (tools ?? []).map(tool => ({
    type: 'function',
    function: {
      name: tool.name,
      description: tool.description,
      parameters: toolInputSchema(tool.inputSchema)
    }
  }));
}

function toolInputSchema(schema: object | undefined): object {
  if (schema === undefined || schema === null || (
    typeof schema === 'object' && !Array.isArray(schema) && Object.keys(schema).length === 0
  )) {
    // Ollama reserializes {} as { type: '', properties: null }, which its
    // template parser rejects. Describe parameterless tools as objects.
    return { type: 'object', properties: {} };
  }
  return schema;
}

function roleToOllama(role: vscode.LanguageModelChatMessageRole): string {
  if (role === vscode.LanguageModelChatMessageRole.Assistant) {
    return 'assistant';
  }

  const systemRole = (vscode.LanguageModelChatMessageRole as unknown as { System?: vscode.LanguageModelChatMessageRole }).System;
  if (systemRole !== undefined && role === systemRole) {
    return 'system';
  }

  return 'user';
}

function toolResultContent(part: vscode.LanguageModelToolResultPart): { content: string; images: string[] } {
  const content: string[] = [];
  const images: string[] = [];

  for (const item of part.content) {
    if (item instanceof vscode.LanguageModelTextPart) {
      content.push(item.value);
      continue;
    }
    if (item instanceof vscode.LanguageModelDataPart) {
      if (item.mimeType.startsWith('image/')) {
        images.push(Buffer.from(item.data).toString('base64'));
        continue;
      }
      if (item.mimeType.startsWith('text/')) {
        content.push(new TextDecoder().decode(item.data));
      } else if (isJsonMimeType(item.mimeType)) {
        content.push(new TextDecoder().decode(item.data));
      }
      continue;
    }
    content.push(JSON.stringify(item));
  }

  return { content: content.join('\n'), images };
}

function isJsonMimeType(mimeType: string): boolean {
  const normalized = mimeType.split(';', 1)[0].trim().toLowerCase();
  return normalized === 'application/json'
    || (normalized.startsWith('application/') && normalized.endsWith('+json'));
}

import {
  formatContextLength,
  isMachineContextTooSmall,
  minimumMachineContextLength
} from './contextLength';
import {
  supportedThinkingLevel,
  type ThinkingPolicy
} from './thinking';

interface LoadedModel {
  name: string;
  contextLength?: number;
}

type ModelMetadataLookup = (model: string) => Promise<unknown>;

interface OllamaModelList {
  models?: readonly unknown[];
}

export interface OllamaDiagnosticsConfiguration {
  readonly url: string;
  readonly headers: Readonly<Record<string, string>>;
}

export type OllamaDiagnosticsConfigurationSource =
  | 'used-provider-group'
  | 'resolved-provider-group'
  | 'workspace-settings';

export interface OllamaDiagnosticsConfigurationSelection {
  configuration: OllamaDiagnosticsConfiguration;
  source: OllamaDiagnosticsConfigurationSource;
}

export class OllamaDiagnosticsConfigurationTracker {
  private lastResolvedConfiguration: OllamaDiagnosticsConfiguration | undefined;
  private lastUsedConfiguration: OllamaDiagnosticsConfiguration | undefined;

  recordResolved(configuration: OllamaDiagnosticsConfiguration): void {
    this.lastResolvedConfiguration = copyConfiguration(configuration);
  }

  recordUsed(configuration: OllamaDiagnosticsConfiguration): void {
    this.lastUsedConfiguration = copyConfiguration(configuration);
  }

  select(workspaceConfiguration: OllamaDiagnosticsConfiguration): OllamaDiagnosticsConfigurationSelection {
    if (this.lastUsedConfiguration) {
      return {
        configuration: copyConfiguration(this.lastUsedConfiguration),
        source: 'used-provider-group'
      };
    }
    if (this.lastResolvedConfiguration) {
      return {
        configuration: copyConfiguration(this.lastResolvedConfiguration),
        source: 'resolved-provider-group'
      };
    }
    return {
      configuration: copyConfiguration(workspaceConfiguration),
      source: 'workspace-settings'
    };
  }
}

export interface OllamaDiagnosticsClient {
  list(): Promise<OllamaModelList>;
  ps(): Promise<OllamaModelList>;
  show(request: { model: string }): Promise<unknown>;
}

export interface OllamaModelInspection {
  availableModels?: string[];
  availableModelsError?: unknown;
  loadedModelLines?: string[];
  loadedModelsError?: unknown;
}

export function ollamaDiagnosticsClientOptions(
  host: string,
  configuredHeaders: Readonly<Record<string, unknown>>,
  request: typeof fetch
): { host: string; headers: Record<string, string>; fetch: typeof fetch } {
  const headers: Record<string, string> = {};
  for (const [name, value] of Object.entries(configuredHeaders)) {
    if (typeof value === 'string') {
      headers[name] = value;
    }
  }
  return { host, headers, fetch: request };
}

export async function inspectOllamaModels(
  client: OllamaDiagnosticsClient
): Promise<OllamaModelInspection> {
  const [availableResult, loadedResult] = await Promise.allSettled([
    client.list(),
    client.ps()
  ]);
  const inspection: OllamaModelInspection = {};
  const availableModels = availableResult.status === 'fulfilled'
    ? availableResult.value.models ?? []
    : [];

  if (availableResult.status === 'fulfilled') {
    inspection.availableModels = modelNames(availableModels);
  } else {
    inspection.availableModelsError = availableResult.reason;
  }

  if (loadedResult.status === 'fulfilled') {
    inspection.loadedModelLines = await loadedModelContextDiagnosticLines(
      loadedResult.value.models ?? [],
      availableModels,
      model => client.show({ model })
    );
  } else {
    inspection.loadedModelsError = loadedResult.reason;
  }

  return inspection;
}

export async function loadedModelContextDiagnosticLines(
  models: readonly unknown[],
  availableModels: readonly unknown[],
  getModelMetadata: ModelMetadataLookup
): Promise<string[]> {
  const loadedModels = models
    .map(loadedLocalModel)
    .filter((model): model is LoadedModel => model !== undefined);

  if (loadedModels.length === 0) {
    return [
      'No local models are currently loaded. Send a prompt to a local Ollama model, then rerun `Ollama: Diagnose Models`.'
    ];
  }

  const modelLines = await Promise.all(loadedModels.map(async model => {
    let maximum = maximumSupportedContextLength(findModelMetadata(availableModels, model.name));
    if (maximum === undefined) {
      try {
        maximum = maximumSupportedContextLength(await getModelMetadata(model.name));
      } catch {
        // Maximum context metadata is optional; the runtime allocation remains useful.
      }
    }
    return loadedModelContextLine(model, maximum);
  }));

  return [
    `Ollama reports ${loadedModels.length} loaded local model(s):`,
    ...modelLines
  ];
}

function findModelMetadata(models: readonly unknown[], requestedModel: string): unknown {
  const requestedKey = modelKey(requestedModel);
  return models.find(candidate => isRecord(candidate) && [candidate.name, candidate.model].some(name =>
    typeof name === 'string' && modelKey(name) === requestedKey
  ));
}

function modelNames(models: readonly unknown[]): string[] {
  return models.flatMap(model => {
    if (!isRecord(model) || typeof model.name !== 'string' || model.name.length === 0) {
      return [];
    }
    return [model.name];
  });
}

export function maximumSupportedContextLength(metadata: unknown): number | undefined {
  if (!isRecord(metadata)) {
    return undefined;
  }

  for (const value of [
    positiveInteger(metadata.max_context_length),
    positiveIntegerField(metadata.details, 'max_context_length'),
    positiveInteger(metadata.context_length),
    positiveIntegerField(metadata.details, 'context_length'),
    modelInfoContextLength(metadata.model_info, 'max_context_length'),
    modelInfoContextLength(metadata.model_info, 'context_length')
  ]) {
    if (value !== undefined) {
      return value;
    }
  }

  return undefined;
}

function loadedLocalModel(candidate: unknown): LoadedModel | undefined {
  if (!isRecord(candidate)) {
    return undefined;
  }

  const name = [candidate.name, candidate.model]
    .find(value => typeof value === 'string' && value.length > 0);
  if (typeof name !== 'string' || isRemoteModel(candidate, name)) {
    return undefined;
  }

  return {
    name,
    contextLength: positiveInteger(candidate.context_length)
  };
}

function loadedModelContextLine(model: LoadedModel, maximum: number | undefined): string {
  const allocation = model.contextLength === undefined
    ? 'unavailable'
    : formatContextLength(model.contextLength);
  const maximumContext = maximum === undefined
    ? 'unavailable'
    : formatContextLength(maximum);
  const warningSuffix = model.contextLength !== undefined && isMachineContextTooSmall(model.contextLength)
    ? `; WARNING: runtime allocation is below the recommended ${formatContextLength(minimumMachineContextLength)}`
    : '';

  return `- ${model.name}: runtime context allocation: ${allocation}; maximum supported context: ${maximumContext}${warningSuffix}`;
}

function isRemoteModel(model: Record<string, unknown>, name: string): boolean {
  if (typeof model.remote_host === 'string' && model.remote_host.length > 0) {
    return true;
  }
  const tag = name.split(':').at(-1)?.toLowerCase() ?? '';
  return tag === 'cloud' || tag.endsWith('-cloud');
}

function modelKey(name: string): string {
  const normalized = name.trim().toLowerCase();
  return normalized.endsWith(':latest')
    ? normalized.slice(0, -':latest'.length)
    : normalized;
}

function modelInfoContextLength(
  modelInfo: unknown,
  expectedKey: 'context_length' | 'max_context_length'
): number | undefined {
  const entries = modelInfo instanceof Map
    ? modelInfo.entries()
    : isRecord(modelInfo)
      ? Object.entries(modelInfo)
      : [];

  for (const [key, value] of entries) {
    const contextLength = positiveInteger(value);
    if ((key === expectedKey || key.endsWith(`.${expectedKey}`)) && contextLength !== undefined) {
      return contextLength;
    }
  }
  return undefined;
}

function positiveIntegerField(value: unknown, key: string): number | undefined {
  return isRecord(value) ? positiveInteger(value[key]) : undefined;
}

function positiveInteger(value: unknown): number | undefined {
  return typeof value === 'number' && Number.isSafeInteger(value) && value > 0
    ? value
    : undefined;
}

function copyConfiguration(configuration: OllamaDiagnosticsConfiguration): OllamaDiagnosticsConfiguration {
  return {
    url: configuration.url,
    headers: { ...configuration.headers }
  };
}

function isRecord(value: unknown): value is Record<string, unknown> {
  return typeof value === 'object' && value !== null && !Array.isArray(value);
}

export interface ThinkingDiagnosticModel {
  readonly model: string;
  readonly thinkingPolicy?: ThinkingPolicy;
  readonly defaultSource?: 'server' | 'compatibility';
}

export function thinkingDiagnosticLines(
  models: readonly ThinkingDiagnosticModel[],
  configuredThinkingLevels?: unknown
): string[] {
  const configuredMap = isRecord(configuredThinkingLevels) ? configuredThinkingLevels : undefined;
  if (models.length === 0) {
    return [];
  }

  const lines: string[] = ['Thinking settings:'];
  for (const model of models) {
    const policy = model.thinkingPolicy;
    const rawOverride = configuredMap && Object.hasOwn(configuredMap, model.model)
      ? configuredMap[model.model]
      : undefined;
    if (!policy) {
      const override = rawOverride === undefined ? 'none' : `${formatThinkingValue(rawOverride)} (ignored)`;
      lines.push(
        `- ${model.model}: configurable thinking values unavailable; configured override: ${override}; think will be omitted to use server default`
      );
      continue;
    }
    const effective = supportedThinkingLevel(policy, rawOverride);
    const defaultLabel = model.defaultSource === 'server'
      ? `server-advertised default: ${formatThinkingValue(policy.defaultLevel)}`
      : model.defaultSource === 'compatibility'
        ? `compatibility fallback default: ${formatThinkingValue(policy.defaultLevel)}`
        : `default: ${formatThinkingValue(policy.defaultLevel)}`;

    const supportedList = `supported values: [${policy.levels.map(formatThinkingValue).join(', ')}]`;

    let overrideStatus: string;
    if (rawOverride === undefined) {
      overrideStatus = 'configured override: none; think will be omitted to use server default';
    } else if (effective !== undefined) {
      overrideStatus = `configured override: ${formatThinkingValue(rawOverride)}; effective setting for next request: ${formatThinkingValue(effective)}`;
    } else {
      overrideStatus = `configured override: ${formatThinkingValue(rawOverride)} (unsupported, ignored); think will be omitted to use server default`;
    }

    lines.push(`- ${model.model}: ${supportedList}; ${defaultLabel}; ${overrideStatus}`);
  }

  return lines;
}

function formatThinkingValue(value: unknown): string {
  if (typeof value === 'boolean') {
    return String(value);
  }
  if (typeof value === 'string') {
    return JSON.stringify(value);
  }
  return String(value);
}

export interface ModelRecommendation {
  model: string;
}

export interface OutdatedModelWarningRequest {
  readonly conversationID: number;
}

interface OutdatedModelWarningConversation {
  readonly id: number;
  history: readonly string[];
  readonly warnedModels: Set<string>;
  lastRequestSucceeded: boolean;
}

export class OutdatedModelWarningTracker {
  private readonly conversations = new Map<number, OutdatedModelWarningConversation>();
  private nextConversationID = 1;

  constructor(private readonly maxChats = 100) {}

  beginRequest(
    history: readonly string[],
    hasAssistantResponse: boolean
  ): OutdatedModelWarningRequest {
    // The VS Code provider API has no chat ID. Treat a successful, assistant-free
    // exact history as a new chat, but keep failed retries and growing histories
    // attached to their existing conversation state.
    const recentConversations = [...this.conversations.values()].reverse();
    const exact = recentConversations.find(conversation => historiesEqual(conversation.history, history));
    let conversation = exact
      ? (hasAssistantResponse || !exact.lastRequestSucceeded ? exact : undefined)
      : (hasAssistantResponse ? longestHistoryPrefix(recentConversations, history) : undefined);

    if (!conversation) {
      if (this.conversations.size >= this.maxChats) {
        const oldestConversationID = this.conversations.keys().next().value;
        if (oldestConversationID !== undefined) {
          this.conversations.delete(oldestConversationID);
        }
      }
      conversation = {
        id: this.nextConversationID++,
        history: [],
        warnedModels: new Set<string>(),
        lastRequestSucceeded: false
      };
    } else {
      this.conversations.delete(conversation.id);
    }

    conversation.history = [...history];
    conversation.lastRequestSucceeded = false;
    this.conversations.set(conversation.id, conversation);
    return { conversationID: conversation.id };
  }

  hasShown(request: OutdatedModelWarningRequest, model: string): boolean {
    return this.conversations.get(request.conversationID)?.warnedModels.has(warningModelKey(model)) ?? false;
  }

  markShown(request: OutdatedModelWarningRequest, model: string): void {
    this.conversations.get(request.conversationID)?.warnedModels.add(warningModelKey(model));
  }

  finishRequest(request: OutdatedModelWarningRequest, succeeded: boolean): void {
    const conversation = this.conversations.get(request.conversationID);
    if (conversation) {
      conversation.lastRequestSucceeded = succeeded;
    }
  }
}

function historiesEqual(left: readonly string[], right: readonly string[]): boolean {
  return left.length === right.length && left.every((message, index) => message === right[index]);
}

function longestHistoryPrefix(
  conversations: readonly OutdatedModelWarningConversation[],
  history: readonly string[]
): OutdatedModelWarningConversation | undefined {
  let match: OutdatedModelWarningConversation | undefined;
  for (const conversation of conversations) {
    if (
      conversation.history.length > 0 &&
      conversation.history.length < history.length &&
      conversation.history.every((message, index) => message === history[index]) &&
      (!match || conversation.history.length > match.history.length)
    ) {
      match = conversation;
    }
  }
  return match;
}

const outdatedAgentModelFamilies = new Set([
  'codellama',
  'llama3',
  'llama3.1',
  'llama3.2',
  'llama3.3',
  'mistral',
  'qwen2.5',
  'qwen2.5-coder',
  'starcoder'
]);

const outdatedDeepSeekR1Tags = new Set([
  '',
  'latest',
  '1.5b',
  '7b',
  '8b',
  '14b',
  '32b'
]);

export function parseModelRecommendations(payload: unknown): ModelRecommendation[] {
  if (!isRecord(payload) || !Array.isArray(payload.recommendations)) {
    return [];
  }

  const recommendations: ModelRecommendation[] = [];
  const seen = new Set<string>();
  for (const item of payload.recommendations) {
    if (!isRecord(item) || typeof item.model !== 'string') {
      continue;
    }
    const model = pinnedRecommendationModel(item.model);
    const key = recommendationKey(model);
    if (!model || seen.has(key)) {
      continue;
    }
    seen.add(key);
    recommendations.push({ model });
  }
  return recommendations;
}

export function isRecommendedModel(
  name: string,
  recommendations: readonly ModelRecommendation[]
): boolean {
  const key = recommendationKey(name);
  return recommendations.some(recommendation => recommendationKey(recommendation.model) === key);
}

export function recommendedReplacement<T extends { name: string }>(
  currentModel: string,
  availableModels: readonly T[],
  recommendations: readonly ModelRecommendation[]
): string | undefined {
  const available = new Map(availableModels.map(model => [recommendationKey(model.name), model.name]));
  const currentKey = recommendationKey(currentModel);
  const recommendation = recommendations.find(candidate =>
    recommendationKey(candidate.model) !== currentKey &&
    isCloudModel(candidate.model) === isCloudModel(currentModel)
  );
  if (!recommendation) {
    return undefined;
  }
  return available.get(recommendationKey(recommendation.model)) ?? recommendation.model;
}

export function isOutdatedAgentModel(name: string): boolean {
  const { family, tag } = normalizedModelReference(name);
  if (outdatedAgentModelFamilies.has(family)) {
    return true;
  }
  return family === 'deepseek-r1' && outdatedDeepSeekR1Tags.has(tag);
}

function recommendationKey(name: string): string {
  const normalized = name.trim().toLowerCase();
  return normalized.endsWith(':latest') ? normalized.slice(0, -':latest'.length) : normalized;
}

function pinnedRecommendationModel(name: string): string {
  const model = name.trim();
  const normalized = model.toLowerCase();
  if (normalized === 'gemma4' || normalized === 'gemma4:latest') {
    return 'gemma4:12b';
  }
  return model;
}

function warningModelKey(name: string): string {
  return name.trim().toLowerCase();
}

function normalizedModelReference(name: string): { family: string; tag: string } {
  const pathParts = name.trim().toLowerCase().split('/');
  const reference = pathParts.at(-1) ?? '';
  const separator = reference.indexOf(':');
  const family = separator >= 0 ? reference.slice(0, separator) : reference;
  let tag = separator >= 0 ? reference.slice(separator + 1) : '';
  if (tag === 'cloud') {
    tag = '';
  } else if (tag.endsWith('-cloud')) {
    tag = tag.slice(0, -'-cloud'.length);
  }
  return { family, tag };
}

function isCloudModel(name: string): boolean {
  const tag = name.split(':').at(-1)?.toLowerCase() ?? '';
  return tag === 'cloud' || tag.endsWith('-cloud');
}

function isRecord(value: unknown): value is Record<string, unknown> {
  return typeof value === 'object' && value !== null && !Array.isArray(value);
}

export type ThinkingLevel = boolean | string;

export interface ThinkingPolicy {
  levels: readonly ThinkingLevel[];
  defaultLevel: ThinkingLevel;
}

// Keep this inventory aligned with the model documentation published on
// ollama.com/library. These mappings were last verified on 2026-08-11:
// - https://ollama.com/library/gpt-oss
// - https://ollama.com/library/deepseek-v4-flash
// - https://ollama.com/library/deepseek-v4-pro
// - https://ollama.com/library/glm-5.2

/**
 * Prefer the exact values and default advertised by /api/show. Older servers
 * omit this metadata, so retain the documented mappings for known models only.
 */
export function thinkingPolicy(modelName: string, family?: string, metadata?: unknown): ThinkingPolicy | undefined {
  if (metadata !== undefined) {
    if (typeof metadata !== 'object' || metadata === null) {
      return undefined;
    }
    const { values, default: defaultLevel } = metadata as { values?: unknown; default?: unknown };
    if (!Array.isArray(values) || !values.every(isThinkingLevel) || !isThinkingLevel(defaultLevel)) {
      return undefined;
    }
    const levels = [...new Set(values)];
    // A single value is not a configurable control (e.g. [false] means no thinking).
    return levels.length > 1 && levels.includes(defaultLevel) ? { levels, defaultLevel } : undefined;
  }

  const identifiers = [modelNameWithoutTag(modelName), family]
    .filter((value): value is string => typeof value === 'string')
    .map(normalizeIdentifier);

  if (identifiers.some(value => value === 'gpt-oss' || value === 'gptoss')) {
    return {
      levels: ['low', 'medium', 'high'],
      defaultLevel: 'medium'
    };
  }

  if (identifiers.some(value => value === 'deepseek-v4-flash' || value === 'deepseek-v4-pro')) {
    return {
      levels: [false, 'high', 'max'],
      defaultLevel: false
    };
  }

  if (identifiers.some(value => value === 'glm-5.2' || value === 'glm5.2')) {
    return {
      levels: ['high', 'max'],
      defaultLevel: 'high'
    };
  }

  return undefined;
}

export function isThinkingLevel(value: unknown): value is ThinkingLevel {
  return typeof value === 'boolean' || (typeof value === 'string' && value.trim().length > 0);
}

export function supportedThinkingLevel(
  policy: ThinkingPolicy | undefined,
  value: unknown
): ThinkingLevel | undefined {
  if (!policy) {
    return undefined;
  }
  if (!isThinkingLevel(value)) {
    return undefined;
  }
  return policy.levels.includes(value) ? value : undefined;
}

function modelNameWithoutTag(modelName: string): string {
  const cloudSuffix = ':cloud';
  const normalized = modelName.toLowerCase();
  if (normalized.endsWith(cloudSuffix)) {
    return normalized.slice(0, -cloudSuffix.length);
  }
  return normalized.split(':', 1)[0];
}

function normalizeIdentifier(value: string): string {
  return value.trim().toLowerCase().replaceAll('_', '-');
}
